/**
 * @name Arbitrary file read
 * @description Reading files with user-controlled paths can lead to unauthorized file access
 * @kind path-problem
 * @problem.severity error
 * @id py/jsonschema-arbitrary-file-read
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module FileReadConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("json").getMember(["load", "loads"]).getACall() |
      source = call
    ) or
    exists(DataFlow::Node sysArgv |
      sysArgv = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource() |
      source = sysArgv
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
  }
}

module FileReadFlow = TaintTracking::Global<FileReadConfig>;
import FileReadFlow::PathGraph

from FileReadFlow::PathNode source, FileReadFlow::PathNode sink
where FileReadFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Arbitrary file read from $@.", source.getNode(), "user input"
